<?php
if ( ! defined( 'ABSPATH' ) ) { exit; }
function sd_customizer_design( $wp_customize ) { $wp_customize->add_section( 'sd_design', array( 'title' => __( 'Design system', 'social-discovery' ), 'panel' => 'sd_settings' ) ); foreach ( array( 'sd_primary_color' => 'Primary color', 'sd_primary_hover' => 'Primary hover', 'sd_secondary_color' => 'Secondary color', 'sd_accent_color' => 'Accent color' ) as $id => $label ) { $wp_customize->add_setting( $id, array( 'default' => sd_get_option( $id ), 'sanitize_callback' => 'sanitize_hex_color' ) ); $wp_customize->add_control( new WP_Customize_Color_Control( $wp_customize, $id, array( 'label' => $label, 'section' => 'sd_design' ) ) ); } $wp_customize->add_setting( 'sd_dark_mode', array( 'default' => 'system', 'sanitize_callback' => 'sd_sanitize_select' ) ); $wp_customize->add_control( 'sd_dark_mode', array( 'label' => 'Appearance mode', 'section' => 'sd_design', 'type' => 'select', 'choices' => array( 'light' => 'Light', 'dark' => 'Dark', 'system' => 'System' ) ) ); $wp_customize->add_setting( 'sd_reading_width', array( 'default' => 760, 'sanitize_callback' => 'sd_sanitize_positive_int' ) ); $wp_customize->add_control( 'sd_reading_width', array( 'label' => 'Reading width', 'section' => 'sd_design', 'type' => 'number', 'input_attrs' => array( 'min' => 560, 'max' => 1000 ) ) ); }
add_action( 'customize_register', 'sd_customizer_design' );
